with customer as (

    select * from {{ ref('stg_tpch_erp__customer') }}

),

nation as (

    select * from {{ ref('stg_tpch_erp__nation') }}

)

select
    cast(customer.c_custkey as BIGINT) as customer_id,
    cast(customer.c_name as VARCHAR) as customer_name,
    cast(customer.c_phone as VARCHAR) as phone,
    cast(nation.n_name as VARCHAR) as nation_name,
    cast(customer.c_mktsegment as VARCHAR) as market_segment,
    cast(customer.c_acctbal as DECIMAL(18,4)) as account_balance
from customer
left join nation
    on customer.c_nationkey = nation.n_nationkey
